async function getSolanaBalance(address) {
    const apiKey = process.env.HELIUS_API_KEY;
    try {
        const res = await fetch(`https://mainnet.helius-rpc.com/?api-key=${apiKey}&t=${Date.now()}`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                jsonrpc: "2.0",
                id: 1,
                method: "getBalance",
                params: [
                    address
                ]
            }),
            cache: "no-store"
        });
        const data = await res.json();
        return Number(data.result?.value || 0) / 1_000_000_000;
    } catch (e) {
        return 0;
    }
}
async function getEVMBalance(address, network) {
    const url = network === "ETHEREUM" ? `https://eth.llamarpc.com` : `https://mainnet.base.org`;
    try {
        const res = await fetch(`${url}?t=${Date.now()}`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                "User-Agent": "Mozilla/5.0"
            },
            body: JSON.stringify({
                jsonrpc: "2.0",
                id: 1,
                method: "eth_getBalance",
                params: [
                    address,
                    "latest"
                ]
            }),
            cache: "no-store"
        });
        const data = await res.json();
        if (data.result) {
            return Number(BigInt(data.result)) / 1e18;
        }
        return 0;
    } catch (e) {
        return 0;
    }
}
async function getBTCBalance(address) {
    const cb = Date.now();
    // ENGINE 1: Blockchair (Sangat ramah Vercel, kebal blokir)
    try {
        const res = await fetch(`https://api.blockchair.com/bitcoin/dashboards/address/${address}?_=${cb}`, {
            cache: "no-store"
        });
        if (res.ok) {
            const data = await res.json();
            const bal = Number(data.data[address].address.balance) / 100_000_000;
            if (!isNaN(bal) && bal >= 0) return bal;
        }
    } catch (e) {
        console.error("Blockchair failed");
    }
    // ENGINE 2: BlockCypher
    try {
        const res = await fetch(`https://api.blockcypher.com/v1/btc/main/addrs/${address}/balance?_=${cb}`, {
            cache: "no-store"
        });
        if (res.ok) {
            const data = await res.json();
            const bal = Number(data.final_balance) / 100_000_000;
            if (!isNaN(bal) && bal >= 0) return bal;
        }
    } catch (e) {
        console.error("BlockCypher failed");
    }
    // ENGINE 3: Blockchain.info
    try {
        const res = await fetch(`https://blockchain.info/q/addressbalance/${address}?_=${cb}`, {
            cache: "no-store"
        });
        if (res.ok) {
            const text = await res.text();
            const bal = Number(text) / 100_000_000;
            if (!isNaN(bal) && bal >= 0) return bal;
        }
    } catch (e) {
        console.error("Blockchain.info failed");
    }
    // ENGINE 4: Mempool.space
    try {
        const res = await fetch(`https://mempool.space/api/address/${address}?_=${cb}`, {
            cache: "no-store"
        });
        if (res.ok) {
            const data = await res.json();
            const funded = Number(data.chain_stats?.funded_txo_sum || 0);
            const spent = Number(data.chain_stats?.spent_txo_sum || 0);
            const bal = (funded - spent) / 100_000_000;
            if (!isNaN(bal) && bal >= 0) return bal;
        }
    } catch (e) {
        console.error("Mempool failed");
    }
    return 0;
}
